head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil35400";
scwin.dtree = undefined;
scwin.contn = null;
scwin.keyword = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — isLogin, submitManualList, submitManualClssId

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.contn = "${fn:replace(submitManual.contn, '\"', '\\\"')}";
        scwin.keyword = "${fn:replace(param.keyword, '\"', '\\\"')}";
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil35400.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_78", attr: "__html", fn: function () { return ([String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : ""))(dma_pageContext.get("keyword")))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("<span class=\"search\">" + String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : ""))(dma_pageContext.get("keyword"))) + "</span> 검색결과") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_isLogin", fn: function(){ return ((dma_pageContext.get("isLogin") ?? "") === 'Y'); } }, { id: "c_when_80", fn: function(){ return (!(String(((dma_pageContext.get("submitManualList") ?? "")) == null ? '' : ((dma_pageContext.get("submitManualList") ?? ""))).length === 0)); } }, { id: "tr_83", fn: function(){ return (!(String(((dma_pageContext.get("submitManualList") ?? "")) == null ? '' : ((dma_pageContext.get("submitManualList") ?? ""))).length === 0)); } }, { id: "tr_87", fn: function(){ return (!(String(((dma_pageContext.get("submitManualList") ?? "")) == null ? '' : ((dma_pageContext.get("submitManualList") ?? ""))).length === 0)); } }, { id: "tr_89", fn: function(){ return (!(String(((dma_pageContext.get("submitManualList") ?? "")) == null ? '' : ((dma_pageContext.get("submitManualList") ?? ""))).length === 0)); } }, { id: "c_otherwise_94", fn: function(){ return (!((!(String(((dma_pageContext.get("submitManualList") ?? "")) == null ? '' : ((dma_pageContext.get("submitManualList") ?? ""))).length === 0)))); } }, { id: "if_keyword", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }, { id: "tr_77", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }, { id: "tr_83", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }, { id: "tr_87", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }, { id: "tr_89", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }, { id: "tr_96", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.keyword" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("keyword")))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.keyword !== "undefined" && scwin.keyword !== null ? scwin.keyword : ""))(dma_pageContext.get("keyword"))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil35400.btn_Search_onclick' }); }
};

