scwin.btn_ViewSubmitManual_onclick = async function(e){
    try {
        await scwin.viewSubmitManual('' + dlt_submitManualList.getCellData(0, "helpClssId") + '')
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil35400.btn_ViewSubmitManual_onclick" });
    }
};

/**
