 * @description Add Favorite xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_AddFavorite_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_AddFavorite_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_AddFavorite_xhr", unresolved: "action:self_submit:tx_fn_AddFavorite_xhr" };
};

/**
 * @method
 * @name tx_fn_DeleteFavorite_xhr
 * @description Delete Favorite xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_DeleteFavorite_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_DeleteFavorite_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_DeleteFavorite_xhr", unresolved: "action:self_submit:tx_fn_DeleteFavorite_xhr" };
};

/**
 * @method
 * @name viewSubmitManual
 * @description view Submit Manual 처리
 * @param {String} _submitManualClssId _submitManualClssId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewSubmitManual = async function (_submitManualClssId) {
    const frm = (document.viewForm || { elements: [] });
    frm.action = "/support/manual.do";
    $c.util.getComponent('dma_SearchReq').set('method', "viewSubmitManualDetail");
    $c.util.getComponent('dma_SearchReq').set('submitManualClssId', _submitManualClssId);
    $c.util.getComponent('dma_SearchReq').set('submitManualClssNm', scwin.dtree.getNodeName(_submitManualClssId));
    const result = await scwin.tx_fn_ViewSubmitManual_xhr();
    const submitManualContextDiv = $c.util.getComponent("submitManualContext");
    submitManualContextDiv.innerHTML = result;
    scwin.dtree.open(_submitManualClssId);
    scwin.dtree.selected(_submitManualClssId);
};

