/**
 * @method
 * @name viewDiv
 * @description view Div 처리
 * @param {String} _divId _divId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewDiv = async function (_divId) {
    if (_divId === 2) {
        (($c.util.getComponent('btn1')) && ($c.util.getComponent('btn1')).removeClass ? ($c.util.getComponent('btn1')).removeClass("on") : console.error('[sdd] removeClass 미지원 컴포넌트: btn1'));
        (($c.util.getComponent('btn2')) && ($c.util.getComponent('btn2')).addClass ? ($c.util.getComponent('btn2')).addClass("on") : console.error('[sdd] addClass 미지원 컴포넌트: btn2'));
        await scwin.getFavorite();
    } else {
        (($c.util.getComponent('btn1')) && ($c.util.getComponent('btn1')).addClass ? ($c.util.getComponent('btn1')).addClass("on") : console.error('[sdd] addClass 미지원 컴포넌트: btn1'));
        (($c.util.getComponent('btn2')) && ($c.util.getComponent('btn2')).removeClass ? ($c.util.getComponent('btn2')).removeClass("on") : console.error('[sdd] removeClass 미지원 컴포넌트: btn2'));
        scwin.divStyleSet(_divId);
    }
};

/**
 * @method
 * @name divStyleSet
 * @description div Style Set 처리
 * @param {String} _divId _divId
 * @returns {void}
 * @hidden N
 */
scwin.divStyleSet = function (_divId) {
    const divCnt = 2;
    for (let i = 1; i <= divCnt; i++) {
        const divObj = $c.util.getComponent('cateDiv' + i);
        if (_divId === i) {
            divObj.style.display = 'inline';
        } else {
            divObj.style.display = 'none';
        }
    }
};

