 */
scwin.fileDown = async function (filename, realFilename) {
    $c.util.getComponent('dma_SearchReq').set('method', 'popupFileDown');
    (document.fileDownForm || { elements: [] }).action = '/common/irDataFileDown.do';
    $c.util.getComponent('dma_SearchReq').set('filename', filename);
    $c.util.getComponent('dma_SearchReq').set('realFilename', realFilename);
